from functools import wraps
import time

def cache_with_timeout(timeout_seconds=300):
    """English textcacheEnglish text"""
    def decorator(func):
        cache = {}
        cache_time = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            current_time = time.time()

            if key in cache:
                cache_timestamp = cache_time[key]
                if current_time - cache_timestamp < timeout_seconds:
                    return cache[key]
                else:
                    del cache[key]
                    del cache_time[key]

            result = func(*args, **kwargs)
            cache[key] = result
            cache_time[key] = current_time
            return result

        return wrapper
    return decorator

# useexample
